274.         requires
275.             old(self).inv(),
276.             size > 0,
277.             size <= old(self)@.num_bits,
278.         ensures
279.             self.inv(),
280.             match result {
281.                 Ok(start) => {
282.                     &&& 0 <= start < self@.num_bits
283.                     &&& 0 < size <= self@.num_bits
284.                     &&& start + (size as int) <= self@.num_bits
285.                     &&& self@.num_bits == old(self)@.num_bits
286.                     &&& self@.all_bits_set_in_range(start as int, start + (size as int))
287.                     &&& old(self)@.all_bits_unset_in_range(
288.                         start as int,
289.                         start + (size as int),
290.                     )
291.                     // Frame: only the allocated range changed.
292.                     &&& forall|i: int|
293.                         0 <= i < self@.num_bits && (i < start || i >= start + (size as int))
294.                             ==> self@.is_bit_set(i) == old(self)@.is_bit_set(
295.                             i,
296.                         )
297.                     // Set-based frame.
298.                     &&& self@.set_bits == old(self)@.set_bits.union(
299.                         BitmapView::range_set(start as int, start + (size as int)),
300.                     )
301.                     &&& self@.usage() == old(self)@.usage() + (size as int)
302.                 },
303.                 Err(_) => {
304.                     &&& !old(self)@.exists_contiguous_free_range(size as int)
305.                     &&& self@ == old(self)@
306.                     &&& *self == *old(self)
307.                 },
308.             },
309.     )]
310.     pub fn alloc_range(&mut self, size: usize) -> Result<usize, Error> {
311.         // TODO: remove this runtime check once all callers are verified.
312.         // Check if the size is valid.
313.         if size == 0 || size > self.number_of_bits {
314.             proof! {
315.                 if size > self.number_of_bits {
316.                     self.lemma_no_free_range_when_size_exceeds(size as int);
317.                 }
318.             }
319.             let reason: &str = "invalid size";
320.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
321.         }
322. 
