324.         if self.usage > self.number_of_bits - size {
325.             proof! {
326.                 self.lemma_no_free_range_when_usage_exceeds(size as int);
327.             }
328.             let reason: &str = "allocation exceeds bitmap capacity";
329.             return Err(Error::new(ErrorCode::OutOfMemory, reason));
330.         }
