 use crate::hal::mem::{
     FrameAddress,
     PageAligned,
     PhysicalAddress,
     TruncatedMemoryRegion,
 };
 use ::arch::mem::{
     self,
     paging::FrameNumber,
 };
 use ::config::constants;
 use ::core::{
     hint::unlikely,
     mem::MaybeUninit,
     sync::atomic::{
         AtomicBool,
         Ordering,
     },
 };
 use ::sparse_bitmap::SparseBitmap;
