51. include!("kpool.spec.rs");
52. 
53. #[cfg(verus_keep_ghost)]
54. include!("kpool.proof.rs");
55. 
56. //==================================================================================================
57. // Inner
58. //==================================================================================================
59. 
60. /// Private state of the kernel pool singleton.
61. #[verus_verify(external_derive)]
62. struct Inner {
63.     /// Base address of the kernel pool.
64.     base: PageAligned<PhysicalAddress>,
65.     /// Bitmap of free frames.
66.     bitmap: Bitmap,
67. }
68. 
69. #[verus_verify]
70. impl Inner {
71.     ///
72.     /// # Description
73.     ///
74.     /// Creates a new kernel pool.
75.     ///
76.     /// # Return Values
77.     ///
78.     /// Upon success, the kernel pool.
79.     ///
80.     #[verus_spec(result =>
81.         requires
82.             base.inv(),
83.             bitmap.inv(),
84.         ensures
85.             result matches Ok(kpool) ==> {
86.                 &&& kpool.inv()
87.                 &&& kpool@.start == base@
88.                 &&& kpool@.num_pages == bitmap@.num_bits
89.                 &&& kpool@.used_page_indices == Set::<int>::new(|i: int| bitmap@.is_bit_set(i))
90.             },
91.     )]
92.     fn new(base: PageAligned<PhysicalAddress>, bitmap: Bitmap) -> Result<Inner, Error> {
93.         // Check if bitmap spans across physically-addressable memory.
94.         let bitmap_capacity: usize = bitmap.number_of_bits();
95.         let kpool_size: usize = match bitmap_capacity.checked_mul(mem::PAGE_SIZE) {
96.             Some(size) => size,
97.             None => {
98.                 let reason: &str = "kernel pool size overflows addressable memory";
99.                 error!("{reason}");
100.                 return Err(Error::new(ErrorCode::InvalidArgument, reason));
101.             },
102.         };
103.         if !is_valid_physical_region(base.into_raw_value(), kpool_size) {
104.             let reason: &str = "kernel pool bitmap spans across physically-addressable memory";
105.             error!("{reason}");
106.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
107.         }
108.         info!("kernel pool: {} frames, {} KB", bitmap_capacity, kpool_size / 1024,);
109. 
110.         Ok(Inner { base, bitmap })
111.     }
112. 
113.     ///
114.     /// # Description
115.     ///
116.     /// Allocates a frame from the kernel pool.
117.     ///
118.     /// # Return Values
119.     ///
120.     /// Upon success, the address of the allocated frame is returned. Upon failure, an error is
121.     /// returned instead.
122.     ///
123.     #[verus_spec(result =>
124.         requires
125.             old(self).inv(),
126.         ensures
127.             self.inv(),
128.             match result {
129.                 Ok(frame) => {
130.                     let page_index = (frame@ - old(self)@.start) / spec_page_size();
131.                     &&& frame.inv()
132.                     &&& 0 <= page_index < old(self)@.num_pages
133.                     &&& !old(self)@.used_page_indices.contains(page_index)
134.                     &&& self@ == KpoolView {
135.                         used_page_indices: old(self)@.used_page_indices.insert(page_index),
136.                         ..old(self)@
137.                     }
138.                 },
139.                 Err(_) => {
140.                     &&& forall|i: int| 0 <= i < old(self)@.num_pages ==> old(self)@.used_page_indices.contains(i)
141.                     &&& self@ == old(self)@
142.                 },
143.             },
144.     )]
