1. // Copyright(c) The Maintainers of Nanvix.
2. // Licensed under the MIT License.
3. 
4. // PhysMemoryManager - Specifications
5. //
6. // This file contains specification functions and view types.
7. 
8. verus! {
9. 
10. use crate::hal::mem::spec_page_size;
11. 
12. pub uninterp spec fn byte_at_address(ptr: int) -> u8;
13. 
14. #[verifier::external_type_specification]
15. pub struct ExErrorCode(sys::error::ErrorCode);
16. #[verifier::external_type_specification]
17. pub struct ExError(sys::error::Error);
18. 
19. #[verifier::external_type_specification]
20. #[verifier::external_body]
21. #[verifier::reject_recursive_types(T)]
22. pub struct ExRefCell<T: core::marker::MetaSized>(core::cell::RefCell<T>);
23. 
24. pub struct KpoolView {
25.     pub start: int,
26.     pub num_pages: int,
27.     pub used_page_indices: Set<int>,
28. }
29. 
30. impl KpoolView {
31. 
32.     pub open spec fn wf(&self) -> bool
33.     {
34.         &&& self.num_pages > 0
35.         &&& self.start % spec_page_size() == 0
36.         &&& forall|i: int| self.used_page_indices.contains(i) ==> 0 <= i < self.num_pages
37.     }
38. 
39.     pub open spec fn range_free(&self, first_page_index: int, count: int) -> bool
40.     {
41.         &&& count > 0
42.         &&& 0 <= first_page_index <= self.num_pages - count
43.         &&& forall|i: int| first_page_index <= i < first_page_index + count ==> !self.used_page_indices.contains(i)
44.     }
45.     
46. }
47. 
48. pub struct UpoolView
49. {
50.     pub allocated_frames: Set<int>,
51.     pub free_frames: Set<int>,
52. }
53. 
54. impl UpoolView
55. {
56.     pub open spec fn wf(&self) -> bool
57.     {
58.         &&& forall|addr: int| self.allocated_frames.contains(addr) ==> addr % spec_page_size() == 0
59.         &&& forall|addr: int| self.free_frames.contains(addr) ==> addr % spec_page_size() == 0
60.         &&& self.allocated_frames.disjoint(self.free_frames)
61.     }
62. }
63. 
64. } // end verus!
65. 
66.

